15	/// Page-first geometry: dimensions and derived strides for one page.
16	///
17	/// Pure value type — no GPU, no allocation. Shared by `KvPool`, `KvState`, `KvDesc`.
18	#[derive(Clone, Copy, Debug)]
19	pub struct KvLayout {
20	    pub page_size: usize,
21	    pub num_layers: usize,
22	    pub num_kv_heads: usize,
23	    pub head_dim: usize,
24	    /// Elements in one K (or V) block: page_size × num_kv_heads × head_dim.
25	    pub kv_block_len: usize,
26	    /// Elements between layers within a page: the format's values per token
27	    /// over the page's tokens and heads (K then V for `KvFormat::Split`).
28	    pub layer_stride: usize,
29	    /// Elements per page (all layers): num_layers × layer_stride.
30	    pub page_stride: usize,
31	    pub storage: KvStorage,
32	    pub format: KvFormat,
33	}
34	
35	impl KvLayout {
36	    pub fn new(
37	        num_layers: usize,
38	        num_kv_heads: usize,
39	        head_dim: usize,
40	        page_size: usize,
41	    ) -> anyhow::Result<Self> {
42	        Self::with_storage(
43	            num_layers,
44	            num_kv_heads,
45	            head_dim,
46	            page_size,
47	            KvStorage::Bf16,
48	        )
49	    }
50	
51	    pub fn with_storage(
52	        num_layers: usize,
53	        num_kv_heads: usize,
54	        head_dim: usize,
55	        page_size: usize,
56	        storage: KvStorage,
57	    ) -> anyhow::Result<Self> {
58	        Self::with_storage_and_format(
59	            num_layers,
60	            num_kv_heads,
61	            head_dim,
62	            page_size,
63	            storage,
64	            KvFormat::Split,
65	        )
66	    }
67	
68	    pub fn with_storage_and_format(
69	        num_layers: usize,
70	        num_kv_heads: usize,
71	        head_dim: usize,
72	        page_size: usize,
73	        storage: KvStorage,
74	        format: KvFormat,
75	    ) -> anyhow::Result<Self> {
76	        let (kv_block_len, layer_stride, page_stride) = pegainfer_kernels::paged_kv::derive_strides(
77	            page_size,
78	            num_kv_heads,
79	            head_dim,
80	            num_layers,
81	            format,
82	        )
83	        .ok_or_else(|| {
84	            anyhow::anyhow!(
85	                "kv layout strides overflow usize or {format:?} does not fit head_dim {head_dim}: \
86	                 {num_layers} layers x {num_kv_heads} heads x {page_size} page"
87	            )
88	        })?;
89	        Ok(Self {
90	            page_size,
91	            num_layers,
92	            num_kv_heads,
93	            head_dim,
94	            kv_block_len,
95	            layer_stride,
96	            page_stride,
97	            storage,
98	            format,
99	        })
100	    }
101	
102	    pub fn kernel_layout(&self) -> pegainfer_kernels::paged_kv::PagedKvLayout {
103	        pegainfer_kernels::paged_kv::PagedKvLayout {
104	            page_size: self.page_size,
105	            num_layers: self.num_layers,
106	            num_kv_heads: self.num_kv_heads,
107	            head_dim: self.head_dim,
108	            kv_block_len: self.kv_block_len,
109	            layer_stride: self.layer_stride,
110	            page_stride: self.page_stride,
111	            storage: self.storage,
112	            format: self.format,
113	        }
114	    }
115	}
