117	struct KvPoolInner {
118	    pool: PagePool,
119	    buffer: CudaSlice<bf16>,
120	    layout: KvLayout,
121	    /// Reserved page for bucket CUDA Graph padding. FlashInfer metadata for
122	    /// padding slots points here with seq_len=1. KV append writes harmless
123	    /// garbage; attention output is discarded.
124	    padding_permit: OwnedPagePermit,
125	}
