127	/// Shared KV backing storage with page-based allocation.
128	///
129	/// Owns a single GPU buffer in page-first layout: each page is a contiguous
130	/// chunk holding all layers' K and V for `page_size` tokens.
131	///
132	/// ```text
133	/// page_i: [L0_K | L0_V | L1_K | L1_V | ... | Ln_K | Ln_V]
134	///          └─ page_size × num_kv_heads × head_dim each ─┘
135	/// ```
136	///
137	/// Cheaply cloneable (Arc). Multiple `KvState`s share the same pool.
138	#[derive(Clone)]
139	pub struct KvPool {
140	    inner: Arc<KvPoolInner>,
141	}
142	
143	impl KvPool {
144	    pub fn new(
145	        ctx: &DeviceContext,
146	        num_layers: usize,
147	        num_kv_heads: usize,
148	        head_dim: usize,
149	        page_size: usize,
150	        num_pages: usize,
151	    ) -> Result<Self> {
152	        Self::with_storage(
153	            ctx,
154	            num_layers,
155	            num_kv_heads,
156	            head_dim,
157	            page_size,
158	            num_pages,
159	            KvStorage::Bf16,
160	        )
161	    }
162	
163	    #[allow(clippy::too_many_arguments)]
164	    pub fn with_storage(
165	        ctx: &DeviceContext,
166	        num_layers: usize,
167	        num_kv_heads: usize,
168	        head_dim: usize,
169	        page_size: usize,
170	        num_pages: usize,
171	        storage: KvStorage,
172	    ) -> Result<Self> {
173	        Self::with_storage_and_format(
174	            ctx,
175	            num_layers,
176	            num_kv_heads,
177	            head_dim,
178	            page_size,
179	            num_pages,
180	            storage,
181	            KvFormat::Split,
182	        )
183	    }
184	
185	    #[allow(clippy::too_many_arguments)]
186	    pub fn with_storage_and_format(
187	        ctx: &DeviceContext,
188	        num_layers: usize,
189	        num_kv_heads: usize,
190	        head_dim: usize,
191	        page_size: usize,
192	        num_pages: usize,
193	        storage: KvStorage,
194	        format: KvFormat,
195	    ) -> Result<Self> {
196	        let layout = KvLayout::with_storage_and_format(
197	            num_layers,
198	            num_kv_heads,
199	            head_dim,
200	            page_size,
201	            storage,
202	            format,
203	        )?;
204	        let total_elements = num_pages.checked_mul(layout.page_stride).ok_or_else(|| {
205	            anyhow::anyhow!(
206	                "KvPool geometry overflows: {num_pages} pages x {} elements per page",
207	                layout.page_stride
208	            )
209	        })?;
210	        // The allocator multiplies by the element size unchecked; answer
211	        // for the byte domain here, before it does.
212	        let total_bytes = total_elements
213	            .checked_mul(layout.storage.elem_bytes())
214	            .ok_or_else(|| {
215	                anyhow::anyhow!(
216	                    "KvPool geometry overflows the byte domain: {total_elements} elements"
217	                )
218	            })?;
219	        let backing_slots = total_bytes.div_ceil(std::mem::size_of::<bf16>());
220	
221	        let buffer: CudaSlice<bf16> = ctx
222	            .stream
223	            .alloc_zeros(backing_slots)
224	            .map_err(|e| anyhow::anyhow!("KvPool alloc failed: {e}"))?;
225	
226	        let pool = PagePool::new(num_pages);
227	        let padding_permit = pool
228	            .try_acquire_many(1)
229	            .expect("pool must have at least 1 page for padding");
230	
231	        Ok(Self {
232	            inner: Arc::new(KvPoolInner {
233	                pool,
234	                buffer,
235	                layout,
236	                padding_permit,
237	            }),
238	        })
239	    }
240	
241	    /// Create an empty per-request KV state.
242	    pub fn alloc(&self) -> KvState {
243	        KvState {
244	            permit: self.inner.pool.try_acquire_many(0).expect("zero acquire"),
245	            seq_len: 0,
246	            pool: self.clone(),
247	        }
248	    }
249	
250	    pub fn layout(&self) -> &KvLayout {
251	        &self.inner.layout
252	    }
253	
254	    /// Every state in this pool is a view into this one buffer, so an
255	    /// executor can hold the pool and take page metadata from a plan rather
256	    /// than from a request's state.
257	    pub fn buffer(&self) -> &CudaSlice<bf16> {
258	        &self.inner.buffer
259	    }
260	
261	    pub fn capacity_pages(&self) -> usize {
262	        self.inner.pool.capacity_pages()
263	    }
264	
265	    pub fn available_pages(&self) -> usize {
266	        self.inner.pool.available_pages()
267	    }
268	
269	    /// Page index reserved for bucket CUDA Graph padding.
270	    pub fn padding_page_id(&self) -> i32 {
271	        self.inner.padding_permit.pages()[0].index() as i32
272	    }
273	
274	    /// The schedule half of an atomic multi-pool admission: reserve from
275	    /// every pool first, commit only when all reservations hold, and let a
276	    /// failure roll the rest back by drop. Growing a request's own permit
277	    /// instead cannot be undone.
278	    pub fn try_reserve(&self, pages: usize) -> Option<KvReservation> {
279	        self.inner
280	            .pool
281	            .try_acquire_many(pages)
282	            .map(|permit| KvReservation { permit })
283	    }
284	}
285	
286	/// Returns its pages on drop unless committed via
287	/// [`KvState::commit_reservation`].
288	pub struct KvReservation {
289	    permit: OwnedPagePermit,
290	}
291	
292	impl KvReservation {
293	    /// Append this reservation's page ids to a row the caller owns. A sliding
294	    /// state rebuilds that row every step, so the pages land in one buffer
295	    /// instead of one `Vec` per reservation.
296	    pub fn extend_page_indices_i32(&self, row: &mut Vec<i32>) {
297	        row.extend(self.permit.pages().iter().map(|p| p.index() as i32));
298	    }
299	}
300	
301	/// Per-request KV state. Parallels `RecurrentState` for linear attention.
302	///
303	/// Holds an RAII page permit that auto-returns pages on drop.
304	pub struct KvState {
305	    permit: OwnedPagePermit,
306	    seq_len: usize,
307	    pool: KvPool,
308	}
309	
310	/// Pages needed to hold `token_count` tokens with the given `page_size`.
311	fn pages_needed(token_count: usize, page_size: usize) -> usize {
312	    token_count.div_ceil(page_size)
313	}
314	
315	fn last_page_len_for(token_count: usize, page_size: usize) -> usize {
316	    if token_count == 0 {
317	        0
318	    } else {
319	        let rem = token_count % page_size;
320	        if rem == 0 { page_size } else { rem }
321	    }
322	}
323	
324	impl KvState {
325	    pub fn seq_len(&self) -> usize {
326	        self.seq_len
327	    }
328	
329	    pub fn last_page_len(&self) -> usize {
330	        last_page_len_for(self.seq_len, self.pool.inner.layout.page_size)
331	    }
332	
333	    /// Page indices as i32 for GPU upload.
334	    pub fn page_indices_i32(&self) -> Vec<i32> {
335	        let mut pages = Vec::with_capacity(self.permit.pages().len());
336	        self.extend_page_indices_i32(&mut pages);
337	        pages
338	    }
339	
340	    /// Append page indices to caller-owned planning storage.
341	    pub fn extend_page_indices_i32(&self, pages: &mut Vec<i32>) {
342	        pages.extend(self.permit.pages().iter().map(|p| p.index() as i32));
343	    }
344	
345	    pub fn buffer(&self) -> &CudaSlice<bf16> {
346	        &self.pool.inner.buffer
347	    }
348	
349	    /// Page ids only mean something against the pool that issued them, so an
350	    /// executor holding a pool must check before indexing its buffer.
351	    pub fn belongs_to(&self, pool: &KvPool) -> bool {
352	        std::sync::Arc::ptr_eq(&self.pool.inner, &pool.inner)
353	    }
354	
355	    pub fn layout(&self) -> &KvLayout {
356	        &self.pool.inner.layout
357	    }
358	
359	    /// Ensure capacity for at least `token_count` tokens total.
360	    pub fn ensure_capacity(&mut self, token_count: usize) -> Result<()> {
361	        let needed = pages_needed(token_count, self.pool.inner.layout.page_size);
362	        let held = self.permit.len();
363	        if needed <= held {
364	            return Ok(());
365	        }
366	        let grow = needed - held;
367	        if !self.permit.try_grow(grow) {
368	            bail!(
369	                "KvState: out of pages (need {grow} more, {} available)",
370	                self.pool.available_pages()
371	            );
372	        }
373	        Ok(())
374	    }
375	
376	    pub fn held_pages(&self) -> usize {
377	        self.permit.len()
378	    }
379	
380	    /// The apply half of an atomic multi-pool admission. The reservation must
381	    /// come from this state's pool, which the permit merge enforces.
382	    pub fn commit_reservation(&mut self, reservation: KvReservation) {
383	        self.permit.absorb(reservation.permit);
384	    }
385	
386	    pub fn advance(&mut self, count: usize) {
387	        self.seq_len += count;
388	    }
389	
390	    pub fn desc(&self) -> KvDesc<'_> {
391	        KvDesc {
392	            pages: self.permit.pages(),
393	            last_page_len: self.last_page_len(),
394	        }
395	    }
396	
397	    pub fn desc_for_len(&self, seq_len: usize) -> Result<KvDesc<'_>> {
398	        let held = self.permit.len();
399	        let needed = pages_needed(seq_len, self.pool.inner.layout.page_size);
400	        anyhow::ensure!(
401	            held == needed,
402	            "KvState holds {held} pages where {seq_len} tokens need exactly {needed}"
403	        );
404	        Ok(KvDesc {
405	            pages: self.permit.pages(),
406	            last_page_len: last_page_len_for(seq_len, self.pool.inner.layout.page_size),
407	        })
408	    }
409	
410	    /// Reset for a new request: return all pages, zero seq_len.
411	    #[cfg(test)]
412	    fn reset(&mut self) {
413	        self.permit = self
414	            .pool
415	            .inner
416	            .pool
417	            .try_acquire_many(0)
418	            .expect("zero acquire");
419	        self.seq_len = 0;
420	    }
421	}
422	
423	/// Kernel-facing metadata describing this request's paged KV layout.
424	///
425	/// Bundles pool geometry (strides) with request state (page list, seq_len).
426	/// Forward code passes this opaquely to FFI calls.
427	pub struct KvDesc<'a> {
428	    pages: &'a [PageId],
429	    last_page_len: usize,
430	}
431	
432	impl KvDesc<'_> {
433	    pub fn last_page_len(&self) -> usize {
434	        self.last_page_len
435	    }
436	
437	    #[cfg(test)]
438	    fn num_pages(&self) -> usize {
439	        self.pages.len()
440	    }
441	
442	    /// Page indices for this request (CPU-side).
443	    pub(crate) fn page_indices(&self) -> &[PageId] {
444	        self.pages
445	    }
446	}
447	
448	#[cfg(test)]
449	mod tests {
450	    use super::*;
451	
452	    fn test_pool(page_size: usize, num_pages: usize) -> KvPool {
453	        let ctx = DeviceContext::new().expect("GPU required for kv_pool tests");
454	        // Tiny allocation: 1 layer, 1 head, dim=1 — just enough to exercise logic.
455	        KvPool::new(&ctx, 1, 1, 1, page_size, num_pages).expect("KvPool::new failed")
456	    }
457	
458	    #[test]
459	    fn storage_width_sets_backing_capacity() {
460	        let ctx = DeviceContext::new().expect("GPU required for kv_pool tests");
461	        let pages = 3;
462	        let fp8 =
463	            KvPool::with_storage(&ctx, 1, 1, 1, 16, pages, KvStorage::E4m3).expect("fp8 KvPool");
464	        let bf16 =
465	            KvPool::with_storage(&ctx, 1, 1, 1, 16, pages, KvStorage::Bf16).expect("bf16 KvPool");
466	        assert_eq!(
467	            fp8.buffer().len(),
468	            (pages * fp8.layout().page_stride).div_ceil(2)
469	        );
470	        assert_eq!(bf16.buffer().len(), pages * bf16.layout().page_stride);
471	    }
472	
473	    #[test]
474	    fn stride_geometry_qwen35() {
475	        // Qwen3.5-4B: 8 full attn layers, 4 KV heads, head_dim=256, page_size=16
476	        let l = KvLayout::new(8, 4, 256, 16).expect("layout");
477	
478	        assert_eq!(l.kv_block_len, 16 * 4 * 256); // 16384 elements
479	        assert_eq!(l.layer_stride, 2 * 16384); // 32768 (K + V)
480	        assert_eq!(l.page_stride, 8 * 32768); // 262144 per page
481	        // bytes: 262144 * 2 = 524288 = 512 KB per page
482	        assert_eq!(l.page_stride * 2, 512 * 1024);
483	    }
484	
485	    #[test]
486	    fn stride_geometry_qwen3() {
487	        // Qwen3-4B: 36 full attn layers, 4 KV heads, head_dim=128, page_size=16
488	        let l = KvLayout::new(36, 4, 128, 16).expect("layout");
489	
490	        // 36 layers × 16384 = 589824 elements per page
491	        assert_eq!(l.page_stride, 589_824);
492	        // bytes: ~1.125 MB per page
493	    }
494	
495	    #[test]
496	    fn kv_state_lifecycle() {
497	        // 5 pages total: 1 reserved for padding, 4 available for requests
498	        let pool = test_pool(16, 5);
499	        let mut kv = pool.alloc();
500	
501	        // Starts empty
502	        assert_eq!(kv.seq_len(), 0);
503	        let desc = kv.desc();
504	        assert_eq!(desc.num_pages(), 0);
505	        assert_eq!(desc.last_page_len(), 0);
506	
507	        // Prefill 10 tokens: needs 1 page
508	        kv.ensure_capacity(10).unwrap();
509	        kv.advance(10);
510	        assert_eq!(kv.seq_len(), 10);
511	        let desc = kv.desc();
512	        assert_eq!(desc.num_pages(), 1);
513	        assert_eq!(desc.last_page_len(), 10);
514	        assert_eq!(pool.available_pages(), 3);
515	
516	        // Decode to 16: still 1 page, last_page_len=16 (full)
517	        for _ in 10..16 {
518	            kv.ensure_capacity(kv.seq_len() + 1).unwrap();
519	            kv.advance(1);
520	        }
521	        let desc = kv.desc();
522	        assert_eq!(desc.num_pages(), 1);
523	        assert_eq!(desc.last_page_len(), 16);
524	
525	        // One more token crosses page boundary: 2 pages
526	        kv.ensure_capacity(kv.seq_len() + 1).unwrap();
527	        kv.advance(1);
528	        assert_eq!(kv.seq_len(), 17);
529	        let desc = kv.desc();
530	        assert_eq!(desc.num_pages(), 2);
531	        assert_eq!(desc.last_page_len(), 1);
532	        assert_eq!(pool.available_pages(), 2);
533	
534	        // Reset returns all pages
535	        kv.reset();
536	        assert_eq!(kv.seq_len(), 0);
537	        assert_eq!(pool.available_pages(), 4);
538	    }
539	
540	    #[test]
541	    fn kv_state_out_of_pages() {
542	        // 3 pages total: 1 padding, 2 available → 32 tokens max
543	        let pool = test_pool(16, 3);
544	        let mut kv = pool.alloc();
545	
546	        kv.ensure_capacity(32).unwrap(); // exactly fits 2 pages
547	        assert!(kv.ensure_capacity(33).is_err()); // needs 3rd page
548	    }
549	
550	    #[test]
551	    fn kv_state_drop_returns_pages() {
552	        // 5 pages total: 1 padding, 4 available
553	        let pool = test_pool(16, 5);
554	        {
555	            let mut kv = pool.alloc();
556	            kv.ensure_capacity(20).unwrap(); // 2 pages
557	            kv.advance(20);
558	            assert_eq!(pool.available_pages(), 2);
559	        }
560	        // Drop returns pages
561	        assert_eq!(pool.available_pages(), 4);
562	    }
563	}
