317	        let format = KvFormat::Folded { rotary: 128 };
318	        let cols: Vec<usize> = (0..512).map(|d| format.permute(512, d)).collect();
319	        let mut seen = vec![false; 512];
320	        for &col in &cols {
321	            assert!(!seen[col], "column {col} taken twice");
322	            seen[col] = true;
323	        }
324	        assert!(seen.iter().all(|&taken| taken));
325	        let rotated: Vec<usize> = (0..64).chain(256..320).collect();
326	        let first: Vec<usize> = rotated.iter().map(|&d| cols[d]).collect();
327	        assert_eq!(first, (0..128).collect::<Vec<_>>());
328	        assert!(
329	            (0..512)
330	                .filter(|d| !rotated.contains(d))
331	                .all(|d| cols[d] >= 128)
332	        );
333	        assert!((0..512).all(|d| KvFormat::Split.permute(512, d) == d));
334	    }
